import React, {  useEffect, useRef, useState,useCallback, act } from 'react';
import { Button } from 'react-bootstrap';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from '../api/axios';
import useWebSocket, { ReadyState } from "react-use-websocket"
import { useStompClient, useSubscription } from 'react-stomp-hooks';
import SockJsClient from 'react-stomp';
import { Client } from '@stomp/stompjs';
import user_icon from '../img/user_icon.png'
import { Flex } from 'antd';


const  Home = () => {
    const[firstRun, setFirstRun] = useState(true)
    const [message, setMessage] = useState('');
    const navigate = useNavigate();
    const location = useLocation();
    const log = location.state?.from?.pathname || "/logout";
	// let user =   localStorage.getItem("email");
    let currentUser = 'jont26.smith@gmail.com';
    let email = currentUser;
    let phone = ''
    const[name, setName] = useState('')
    const [loadedMessages, setLoadedMessages] = useState([])
    const [thisMessage, setThisMessage] = useState('')
    const[allMessages, setAllMessage] = useState([])
    const[username, setUsername] = useState('')
    const testUser = 'jt010051'
    const otherUser = 'jt0100'
    const [activeUser, setActiveUser] = useState(false);
    const [listOfUsers, setListOfUsers] = useState([])
	const [selectedUser, setSelectedUser] = useState('')
    const [recievedMessages, setRecievedMessages] = useState(false)
let userChat = null;

const [userChatResponse, setUserChatResponse] = useState([]);
const[responseMap, setResponseMap] = useState([])
     const findAndDisplayConnectedUsers = async(e) =>{

        try{
        const connectedUsersList  = await axios.get('user/allUsers');
        setListOfUsers(connectedUsersList.data

            .filter( user => user.email !== email)
            .filter( user => user.phone !== phone)

            .map(user => user.firstName))








        }
        catch (err) {
            console.log(err);

        }

    }



    const   fetchAndDisplayUserChat = async()=>{


 setUserChatResponse(await axios.get(`/messages/${currentUser}/${selectedUser}`))









        // chatArea.scrollTop = chatArea.scrollHeight
    }


    const stompClient = useStompClient();
    const publishMessage = () => {
        console.log(selectedUser);

        if(stompClient) {
            const chatMessage = {
                senderId: currentUser,
                recipientId: selectedUser,
                content: thisMessage,
                timeStamp: new Date() 
            }
          stompClient.publish({destination: '/app/chat', body: JSON.stringify(chatMessage)})
        //   displayMessage(currentUser, thisMessage)

        }
      }
if (!currentUser) {
    currentUser = localStorage.getItem("phone");
}


const userDetailsApi = `user/userDetails/${currentUser}`



const logout =()=>{
    navigate(log, { replace: true });

}


// getUserDetails()


let nickname = null;
let fullname = null;
const recievedMsgs = () =>{
    userChatResponse.data.forEach(()=>{
        return (
            <>Hello World</>
        )
    })


}
useEffect(()=>{
findAndDisplayConnectedUsers()

},[])
useEffect(()=>{
if(activeUser){
    fetchAndDisplayUserChat()



}



},[activeUser])




    return (

      <>

      <h2>Hello {name}</h2>



<div className="chat-container" id="chat-page">
    <div className="users-list">
        <div className="users-list-container">
            <h2>Online Users</h2>
            <ul id="connectedUsers" >

            </ul>
        </div>
        <div>
            <p id="connected-user-fullname"></p>

       {listOfUsers
            .map(user => {
                return   (
                <ul>
                <li className={['user-item', activeUser ? 'active':null].join(" ")} 
            onClick={(e)=>{
                setActiveUser(!activeUser)
                setSelectedUser(user)

            }}><img src={user_icon} alt = {user} style={{width:20, height: 20}} />
            <span>
            {user}
            </span>
           {recievedMessages ?
             <span className='nbr-msg'>

         </span> : null
           }
 </li>
 </ul>
                )
            }
            )}


        </div>
    </div>

    <div className="chat-area">
        <div className="chat-area" id="chat-messages">





{
activeUser && userChatResponse.data? 
<>
{
    recievedMsgs()
}


</>  



: null


}




        </div>
         {activeUser ? 
         <>


<form id="messageForm" name="messageForm" >
<div className="message-input">
<input autoComplete="off" type="text" id="message" placeholder="Type your message..."
        onChange={(e) => setThisMessage(e.target.value)}  />
        <Button onClick={publishMessage}>Send</Button>

            </div>
         </form>

         </>
         : null}
  </div>







</div>
   <script src="https://cdnjs.cloudflare.com/ajax/libs/sockjs-client/1.1.4/sockjs.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/stomp.js/2.3.3/stomp.min.js"></script>   
<Button  onClick={logout}>Logout</Button>


      </>
    );
}

export default Home;
